using System.Security.Cryptography;
using Dapper;
using Microsoft.AspNetCore.Identity;
using Npgsql;

internal sealed class PasswordResetStore
{
    internal static readonly TimeSpan Lifetime = TimeSpan.FromMinutes(20);
    internal const int MaxActiveTokens = 3;
    private readonly string _connectionString;
    private readonly byte[] _key;
    private static readonly PasswordHasher<object> Hasher = new();
    private static readonly object HashUser = new();

    // The supplied base64 key must be dedicated to this service and generated by a CSPRNG.
    internal PasswordResetStore(string connectionString, string? base64Key)
    {
        byte[] key;
        try
        {
            key = Convert.FromBase64String(base64Key ?? "");
        }
        catch (FormatException)
        {
            throw new ArgumentException("Invalid password reset key.", nameof(base64Key));
        }
        if (key.Length < 32 || key.Length > 64 || key.All(value => value == key[0]))
            throw new ArgumentException("Invalid password reset key.", nameof(base64Key));
        _connectionString = connectionString;
        _key = key;
    }

    // The caller must deliver the returned token securely and never log or persist it.
    internal async Task<string?> IssueAsync(Guid userId, CancellationToken cancellationToken = default)
    {
        await using var connection = new NpgsqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken);
        await using var transaction = await connection.BeginTransactionAsync(cancellationToken);
        if (!await LockCredentialAsync(connection, transaction, userId, cancellationToken))
            return null;

        var active = await connection.ExecuteScalarAsync<int>(new CommandDefinition(@"
            select count(*)::int from hic_password_reset_tokens
            where user_id = @userId and invalidated_at_utc is null and expires_at_utc > clock_timestamp();",
            new { userId }, transaction, cancellationToken: cancellationToken));
        if (active >= MaxActiveTokens)
            return null;

        var token = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));
        var verifier = ComputeVerifier(token);
        await connection.ExecuteAsync(new CommandDefinition(@"
            insert into hic_password_reset_tokens (verifier, user_id, expires_at_utc)
            values (@verifier, @userId, now() + @lifetime);",
            new { verifier, userId, lifetime = Lifetime }, transaction, cancellationToken: cancellationToken));
        await transaction.CommitAsync(cancellationToken);
        return token;
    }

    internal async Task<bool> ResetPasswordAsync(Guid userId, string? token, string? newPassword,
        CancellationToken cancellationToken = default)
    {
        if (!TryVerifier(token, out var verifier) || string.IsNullOrEmpty(newPassword) || newPassword.Length > 1024)
            return false;

        await using var connection = new NpgsqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken);
        await using var transaction = await connection.BeginTransactionAsync(cancellationToken);
        if (!await LockCredentialAsync(connection, transaction, userId, cancellationToken))
            return false;

        var consumed = await connection.ExecuteAsync(new CommandDefinition(@"
            update hic_password_reset_tokens set invalidated_at_utc = clock_timestamp()
            where user_id = @userId and verifier = @verifier
              and invalidated_at_utc is null and expires_at_utc > clock_timestamp();",
            new { userId, verifier }, transaction, cancellationToken: cancellationToken));
        if (consumed != 1)
            return false;

        var hash = Hasher.HashPassword(HashUser, newPassword);
        await connection.ExecuteAsync(new CommandDefinition(@"
            update local_password_credentials set password_hash = @hash, updated_at_utc = now()
            where user_id = @userId;
            update hic_user_sessions set revoked_at_utc = now()
            where user_id = @userId and revoked_at_utc is null;
            update hic_password_reset_tokens set invalidated_at_utc = now()
            where user_id = @userId and invalidated_at_utc is null;",
            new { userId, hash }, transaction, cancellationToken: cancellationToken));
        await transaction.CommitAsync(cancellationToken);
        return true;
    }

    internal async Task<bool> CancelAsync(Guid userId, string? token, CancellationToken cancellationToken = default)
    {
        if (!TryVerifier(token, out var verifier))
            return false;
        await using var connection = new NpgsqlConnection(_connectionString);
        return await connection.ExecuteAsync(new CommandDefinition(@"
            update hic_password_reset_tokens set invalidated_at_utc = clock_timestamp()
            where user_id = @userId and verifier = @verifier and invalidated_at_utc is null
              and expires_at_utc > clock_timestamp();",
            new { userId, verifier }, cancellationToken: cancellationToken)) == 1;
    }

    private byte[] ComputeVerifier(string token) =>
        HMACSHA256.HashData(_key, Convert.FromBase64String(token));

    private bool TryVerifier(string? token, out byte[] verifier)
    {
        verifier = [];
        if (token is null || token.Length != 44)
            return false;
        Span<byte> bytes = stackalloc byte[32];
        if (!Convert.TryFromBase64String(token, bytes, out var length) || length != bytes.Length ||
            Convert.ToBase64String(bytes) != token)
            return false;
        verifier = HMACSHA256.HashData(_key, bytes);
        return true;
    }

    private static async Task<bool> LockCredentialAsync(NpgsqlConnection connection, NpgsqlTransaction transaction,
        Guid userId, CancellationToken cancellationToken) =>
        await connection.ExecuteScalarAsync<Guid?>(new CommandDefinition(
            "select user_id from local_password_credentials where user_id = @userId for update;",
            new { userId }, transaction, cancellationToken: cancellationToken)) is not null;
}

internal static class PasswordResetSchema
{
    internal static string MigrationSql
    {
        get
        {
            using var stream = typeof(PasswordResetSchema).Assembly.GetManifestResourceStream("HicPasswordResetMigration")
                ?? throw new InvalidOperationException("Password reset migration resource is missing.");
            using var reader = new StreamReader(stream);
            return reader.ReadToEnd();
        }
    }
}
